INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3671, 'ធុងសាំងរាងស៊ីឡាំងមាន \(h = 1.50\ \text{m}\) និង \(R = 0.4\ \text{m}\)។ គណនាផ្ទៃក្រឡាខាង ផ្ទៃក្រឡាបាតទាំងពីរ និងផ្ទៃក្រឡាទាំងអស់ (\(\pi = 3.14\))។', NULL, '[]', 0, NULL, 5, 'writing', '\(\mathcal{A}_L = 2\pi R h = 2 \times 3.14 \times 0.4 \times 1.5 = 3.768\ \text{m}^2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3672, 'ប្រអប់សំបុត្រមួយមានបាតរាងប្រលេពីប៉ែតកែង \(4 \times 6 \times 12\ \text{cm}\) និងគម្របរាងកន្លះស៊ីឡាំងអង្កត់ផ្ចិត \(4\ \text{cm}\) បណ្តោយ \(12\ \text{cm}\)។ គណនាមាឌ (\(\pi \approx \dfrac{22}{7}\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រលេពីប៉ែតកែង \(V_1 = 4 \times 6 \times 12 = 288\ \text{cm}^3\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3673, 'ធុងសាំងរថយន្តរាងស៊ីឡាំងអង្កត់ផ្ចិត \(68\ \text{cm}\) និងបណ្តោយ \(42\ \text{cm}\) (\(\pi \approx \dfrac{22}{7}\))។ ក. ចំណុះជាលីត្រ។ ខ. ឡានចំណាយសាំង \(8\ \ell\) ក្នុង \(100\ \text{km}\) ឡានដើរបានប៉ុន្មាន km ពេញធុង?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(R = 34\ \text{cm}\) ; \(V = \dfrac{22}{7} \times 34^2 \times 42 = 152\,592\ \text{cm}^3\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3674, 'លួសស្ពាន់មួយចង្វាយប្រវែង \(150\ \text{m}\) អង្កត់ផ្ចិត \(0.6\ \text{cm}\) ម៉ាសមាឌ \(8.9\ \text{kg/dm}^3\)។ គណនាម៉ាសលួស (\(\pi = 3.14\))។', NULL, '[]', 0, NULL, 5, 'writing', 'កាំ \(R = 0.3\ \text{cm} = 0.03\ \text{dm}\) ; ប្រវែង \(1\,500\ \text{dm}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3675, 'អាងទឹករាងប្រលេពីប៉ែតកែងមានបាត \(2\ \text{m} \times 1.5\ \text{m}\) ជម្រៅ \(1.2\ \text{m}\)។ ក. ចំណុះអតិបរមាជាលីត្រ។ ខ. បើចាក់ទឹក \(2\,000\ \ell\) ទឹកនៅកម្ពស់ប៉ុន្មាន? គ. នៅអាចចាក់បន្ថែមប៉ុន្មានលីត្រ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(V = 2 \times 1.5 \times 1.2 = 3.6\ \text{m}^3 = 3\,600\ \ell\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3676, 'ក្រុមហ៊ុនផលិតកំប៉ុងស៊ីឡាំងកាំ \(5\ \text{cm}\) កម្ពស់ \(12\ \text{cm}\) (\(\pi = 3.14\))។ ក. ចំណុះជា ml (\(1\ \text{cm}^3 = 1\ \text{ml}\))។ ខ. ក្រដាសស្លាកជុំវិញកំប៉ុង (ផ្ទៃខាង)។ គ. ក្នុង \(24\) កំប៉ុង ចំណុះសរុបជាលីត្រ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(V = 3.14 \times 25 \times 12 = 942\ \text{cm}^3 = 942\ \text{ml}\) (2 ពិន្ទុ)
